import{_ as l,h as o,i as e,c as h,v as t,p as n,x as r,m as s,e as d,S as A}from"./chunks/framework.Dvtg8yj2.js";const M=JSON.parse('{"title":"MQA 论文","description":"","frontmatter":{"title":"MQA 论文","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/shazeer-mqa.md","filePath":"llm/shazeer-mqa.md","lastUpdated":1788454257000}'),m={name:"llm/shazeer-mqa.md"};function p(_,a,c,E,V,u){const i=o("Mermaid");return e(),h("div",null,[a[1]||(a[1]=t('<h1 id="mqa-论文" tabindex="-1">MQA 论文 <a class="header-anchor" href="#mqa-论文" aria-label="Permalink to &quot;MQA 论文&quot;">​</a></h1><div class="epigraph"><p>增量解码时，每一步都要把历史键值从内存读进计算单元；键和值若在所有查询头之间共享，写头只需一个，带宽随头数下降。</p><footer>—— Shazeer, Fast Transformer Decoding: One Write-Head is All You Need, 2019</footer></div><p>Noam Shazeer 2019 年的短文 <em>Fast Transformer Decoding</em> 把自回归 Transformer 的服务瓶颈写成一条带宽账，而不是又一条注意力变体竞赛。多头注意力为每个头准备独立的键、值投影，训练和前填都好算；一旦进入逐步生成，每写出一个词都要重读全部历史 KV，流量与头数成正比。论文的处方后来被称作 Multi-Query Attention（MQA）：查询头保持多套，键值头减到一套。标题里的 write-head 指的是「每步新写出的那一份 KV」，不是训练时的写回。四年后的 <a href="/llm/ainslie-gqa">GQA</a> 把这一端点放松成分组；本篇只把 2019 年这条极值走完。结构综述见 <a href="/llm/mqa">MQA</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解码第 \\(t\\) 步的新查询每头只有一条向量，点积次数是 \\(t\\cdot h\\)，相对前填的 \\(t^2\\) 已经小很多。真正贵的是加载 \\(K_{1:t},V_{1:t}\\)。完整 MHA 的缓存形状是 \\([t,h,d_k]\\) 的键加同样的值，字节数与 \\(h\\) 成正比。头数随模型变宽而增加时，单步延迟越来越像「搬历史」。批大小一大，缓存更是容量杀手。</p><p>Shazeer 的观察针对的是增量推理，不是训练损失面。许多任务上，各头的查询方向差异比键值方向差异更重要：查询负责「这一头在问什么」，键值负责「上下文里有什么可被问」。后者在头之间高度相关，独立存储的收益递减，读取成本却线性上涨。把键值头数设为 1，是把这一观察做成硬约束。论文用机器翻译解码来量速度，因为编码器-解码器的解码器侧恰好是逐步读缓存的典型负载。</p><h3 id="带宽界-不是算术界" tabindex="-1">带宽界，不是算术界 <a class="header-anchor" href="#带宽界-不是算术界" aria-label="Permalink to &quot;带宽界，不是算术界&quot;">​</a></h3><p>令带宽为 \\(B\\) 字节每秒，单步要读 \\(2\\cdot t\\cdot h\\cdot d_k\\cdot b\\) 字节（\\(b\\) 为每元素字节）。算术量大约是 \\(2\\cdot t\\cdot h\\cdot d_k\\) 次乘加。对解码，算术强度往往低到被带宽饱和。把 \\(h\\) 换成 1，读量降到约 \\(1/h\\)；若查询头仍为 \\(h\\)，点积次数不变——它们点积同一份 \\(K\\)。于是算术强度上升，计算单元开始吃得饱。这是原文要优化的对象。二次阶本身没动：第 \\(n\\) 步仍与 \\(n\\) 成线性关系。</p><p><span class="marginnote">「One Write-Head」容易读成训练时只更新一个头。原文指增量解码：每步只向缓存追加一套 \\(K,V\\)，而不是 \\(h\\) 套。训练仍对共享的 \\(W^K,W^V\\) 回传全部查询头的梯度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设查询头数为 \\(h\\)，键值头数为 1。输入 \\(X\\) 投影出 \\(Q\\in\\mathbb{R}^{n\\times h\\times d_k}\\)，但</p> \\[K=XW^K,\\qquad V=XW^V, \\]<p>\\(W^K,W^V\\in\\mathbb{R}^{d\\times d_k}\\)，得到 \\(K,V\\in\\mathbb{R}^{n\\times 1\\times d_k}\\)。每个查询头 \\(i\\) 计算</p> \\[\\mathrm{head}_i=\\mathrm{softmax}\\bigl(Q_i K^\\top/\\sqrt{d_k}\\bigr)V. \\]<p>拼头后的 \\(W^O\\) 与 MHA 相同。因果掩码、缩放规则都不改。训练时 \\(K,V\\) 在序列维上仍可一次算完；解码时缓存只追加形状 \\([1,d_k]\\) 的一对向量。</p><p>原文的实验设置是编码器-解码器机器翻译（WMT 英德一类），把多查询用在解码器自注意力，有时也用在交叉注意力。编码器没有逐步解码，改 MQA 的动机弱。论文同时讨论与局部注意力的组合：窗口减的是 \\(n\\)，MQA 减的是 \\(h_{\\mathrm{KV}}\\)，两者正交。这不是后来稀疏注意力论文的主线，只是 2019 年加速解码的配套选项。</p>',16)),(e(),n(A,null,{default:r(()=>[d(i,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%E8%BE%93%E5%85%A5%22%5D%20--%3E%20Q%5B%22h%20%E5%A5%97%20Query%22%5D%0A%20%20X%20--%3E%20KV%5B%221%20%E5%A5%97%20Key%20%2F%20Value%22%5D%0A%20%20Q%20--%3E%20A%5B%22%E5%90%84%E5%A4%B4%E5%AF%B9%E5%90%8C%E4%B8%80%20K%20%E6%89%93%E5%88%86%22%5D%0A%20%20KV%20--%3E%20A%0A%20%20A%20--%3E%20Y%5B%22%E6%8B%BC%E6%8E%A5%E5%90%8E%E8%BE%93%E5%87%BA%E6%8A%95%E5%BD%B1%22%5D%0A%20%20KV%20--%3E%20CACHE%5B%22%E6%AF%8F%E6%AD%A5%E5%8F%AA%E8%BF%BD%E5%8A%A0%E4%B8%80%E5%A5%97%20KV%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="从多头检查点出发不是原文的主路径" tabindex="-1">从多头检查点出发不是原文的主路径 <a class="header-anchor" href="#从多头检查点出发不是原文的主路径" aria-label="Permalink to &quot;从多头检查点出发不是原文的主路径&quot;">​</a></h3><p>Shazeer 的设定是为加速解码而设计结构，实验可以随模型一起训，并不依赖「先有 MHA 再蒸馏」。把 \\(h\\) 组 \\(W^K_i,W^V_i\\) 平均成一组，会造成瞬时质量下跌，需要上训练——这条工序是 2023 年 GQA 论文才写成标准流程。回顾时可以把 MQA 看成 GQA 在组数等于 1 时的端点，但 2019 年文本里没有分组旋钮，只有这一端点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共享 KV 意味着所有查询头在同一个键几何里检索。头与头的差异只能来自 \\(Q_i\\) 与 \\(W^O\\) 的对应块：它们可以对同一组键打出不同的分数分布，从而读出不同的值混合。值也只有一份，不同混合来自不同权重，而不是来自不同的值子空间。与 MHA 相比，内容库变薄，提问方式仍多。这解释了论文观察到的「可用、但略差」：翻译这类强对齐任务会先露出缺口，语言模型的损失差通常更小——后者也是 MQA 后来在自回归 LM 文献里站稳的原因。</p><p>梯度上，\\(W^K,W^V\\) 收到全部查询头的误差总和，更新更稳、也更折中。某个头若需要一种很偏的键方向，会与其他头打架。训练初期表现为损失略高；训练后期表现为稀有标记、精确位置一类细粒度对齐变弱。实现上要把共享的 \\(K,V\\) 广播到 \\(h\\) 个头再做批量化点积：正向广播，反向对 KV 投影求和。错误地把 \\(K\\) 扩成 \\(h\\) 头却共享存储指针，容易在反向里重复累加梯度。</p><p><span class="marginnote">论文用翻译延迟说话，因为那是 2019 年 Transformer 服务的主场景。今天用它来论证解码器-only 大模型「MQA 一定够用」，超出了原文证据。大模型头数更多、序列更长，质量坑会比 WMT 上更深，这正是后来停在 GQA 而不是停在 MQA 的原因。</span></p><h3 id="前填几乎无收益" tabindex="-1">前填几乎无收益 <a class="header-anchor" href="#前填几乎无收益" aria-label="Permalink to &quot;前填几乎无收益&quot;">​</a></h3><p>前填阶段 \\(Q,K,V\\) 都从当前序列现场算，HBM 上的 KV 还不必反复读历史。MQA 减少的投影量只有 \\(K,V\\) 两张矩阵的宽度，前填加速通常是几个百分点。解码阶段历史只读不写投影，加速可以接近头数比。原文因此是一篇推理系统论文，挂在注意力结构名下。若工作负载几乎全是训练或超长前填、很少生成，MQA 的动机变弱。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>质量回归是核心代价。头数很大的模型把 KV 压到 1 头，等于让上百个查询共享一个内容库。批很小、长度很短时，解码本就不是带宽界，MQA 几乎白付质量。批很大、长度很长时，缓存按 \\(1/h\\) 下降，同卡可服务的并发显著上升——产品上这往往比单请求的一点点 BLEU 更值钱。</p><p>张量并行是原文几乎没写、工程上立刻碰到的问题。KV 头只有 1，不能再按头切分到多卡；查询头仍可切。注意力子层的并行策略因此不对称。单机服务无此问题；多卡解码需要改切分或把 KV 复制到各卡。GQA 用 \\(h_{kv}=8\\) 一类取值，既收回大部分质量，也让切分重新变得整齐。选择停在 MQA，意味着明确接受「单内容库、多提问」，以及切分上的别扭。</p><p><span class="marginnote">不要把 MQA 和「共享投影但推理时再复制成多头缓存」混为一谈。若服务栈仍按 \\(h\\) 头去读，带宽账一本没改，只是训练时省了参数。原文的收益以推理时真正只存一套 KV 为前提。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MQA 论文把增量解码写成带宽问题：保留多套查询头，全头共享一套键值。</li><li>每步只向缓存追加一套 KV，读取量约为 MHA 的 \\(1/h\\)。</li><li>各头仍可对同一 \\(K\\) 打出不同分数，但值子空间不再按头分化，这是质量损失的来源。</li><li>证据来自编码器-解码器翻译解码；前填加速有限。</li><li>从 MHA 改造并上训练不是 2019 年的主线，而是后来 GQA 论文补上的工序。</li><li>张量并行难以按 KV 头切分，是端点结构的系统代价。</li><li>出处：Shazeer, <em>Fast Transformer Decoding: One Write-Head is All You Need</em>, 2019。</li></ul>',14))])}const Q=l(m,[["render",p]]);export{M as __pageData,Q as default};
